    function handleHeroDescPaste(e) {
        const items = (e.clipboardData || e.originalEvent?.clipboardData)?.items;
        if (!items) return;
        for (const item of items) {
            if (!item.type.startsWith('image/')) continue;
            e.preventDefault();
            const reader = new FileReader();
            reader.onload = ev => {
                const editor = document.getElementById('haDescEditor');
                if (!editor) return;
                editor.focus();
                document.execCommand('insertHTML', false,
                    `<img src="${ev.target.result}" style="max-width:100%;border-radius:4px;margin:4px 0;display:block;">`);
                syncHeroDescFromEditor();
            };
            reader.readAsDataURL(item.getAsFile());
            return;
        }
        setTimeout(syncHeroDescFromEditor, 0);
    }

    // 관리자가 저장한 서식은 유지하되 스크립트/이벤트 속성은 표시 전 제거한다.
    function sanitizeHeroDescriptionHtml(html) {
        const template = document.createElement('template');
        template.innerHTML = String(html || '');
        const allowedTags = new Set(['B','STRONG','I','EM','U','BR','DIV','P','UL','OL','LI','BLOCKQUOTE','A','IMG','SPAN']);
        [...template.content.querySelectorAll('*')].forEach(el => {
            if (!allowedTags.has(el.tagName)) {
                el.replaceWith(...el.childNodes);
                return;
            }
            [...el.attributes].forEach(attr => {
                const name = attr.name.toLowerCase();
                const keep = (el.tagName === 'A' && ['href','target','rel'].includes(name)) ||
                    (el.tagName === 'IMG' && ['src','alt'].includes(name));
                if (!keep) el.removeAttribute(attr.name);
            });
            if (el.tagName === 'A') {
                const href = el.getAttribute('href') || '';
                if (!/^(https?:|mailto:|\/)/i.test(href)) el.removeAttribute('href');
                el.setAttribute('rel', 'noopener noreferrer');
            }
            if (el.tagName === 'IMG') {
                const src = el.getAttribute('src') || '';
                if (!/^(https?:|data:image\/)/i.test(src)) el.remove();
            }
        });
        return template.innerHTML;
    }

    // 자연 설명 에디터 → proxy textarea + castleDesc + castleDescEditor 동기화
