    // 클립보드 붙여넣기 처리 (이미지 데이터 + URL 텍스트)
    function handleDescPaste(e) {
        const targetEl = e.currentTarget || e.target;
        const isNaturalEditor = targetEl?.id === 'naturalDescEditorProxy';
        const items = (e.clipboardData || e.originalEvent?.clipboardData)?.items;
        if (!items) return;

        // 이미지 파일(클립보드 캡처 등) → 서버 업로드 없이 base64 미리보기
        for (const item of items) {
            if (item.type.startsWith('image/')) {
                e.preventDefault();
                const blob = item.getAsFile();
                const reader = new FileReader();
                reader.onload = (ev) => {
                    const editor = isNaturalEditor
                        ? document.getElementById('naturalDescEditorProxy')
                        : document.getElementById('castleDescEditor');
                    if (!editor) return;
                    editor.focus();
                    const img = `<img src="${ev.target.result}" style="max-width:100%;border-radius:4px;margin:4px 0;display:block;">`;
                    document.execCommand('insertHTML', false, img);
                    if (isNaturalEditor) syncNaturalDesc(editor); else syncDescFromEditor();
                };
                reader.readAsDataURL(blob);
                return;
            }
        }
        // 텍스트/HTML 붙여넣기는 기본 동작 허용 후 동기화
        setTimeout(() => {
            if (isNaturalEditor) {
                const el = document.getElementById('naturalDescEditorProxy');
                if (el) syncNaturalDesc(el);
            } else {
                syncDescFromEditor();
            }
        }, 0);
    }

    // 에디터 초기화 (폼 열 때 호출)
