            'buffalo': { symbol: '🐃', className: 'feature-other' },
            'horse': { symbol: '🐎', className: 'feature-other' },
            'camel': { symbol: '🐫', className: 'feature-other' },
            'mongky': { symbol: '🐒', className: 'feature-other' },
            'hunting': { symbol: '🏹', className: 'feature-hunting' },
            'construction': { symbol: '⚒️', className: 'feature-construction' },
            'tomb': { symbol: '🪦', className: 'feature-tomb', imageUrl: 'https://wumvyfnefyefzo3c.public.blob.vercel-storage.com/map-icons/natural-tomb.png' }, // 고분/묘
            'temple': { symbol: '🏛', className: 'feature-temple', imageUrl: 'https://wumvyfnefyefzo3c.public.blob.vercel-storage.com/map-icons/natural-temple.png', imageSize: 15 }, // 사원/신전
            'palace': { symbol: '🏯', className: 'feature-palace' }, // 궁전
