            'kiln': { symbol: '🔥', className: 'feature-kiln' }, // 가마/도요지
            'farmland': { symbol: '🌾', className: 'feature-farmland' }, // 농경지
            'heritage': { symbol: '🏺', className: 'feature-heritage', imageUrl: 'https://wumvyfnefyefzo3c.public.blob.vercel-storage.com/map-icons/natural-heritage.png', imageSize: 15, anchorBottom: true }, // 유적
            'battle': { symbol: '⚔️', className: 'feature-battle' }, // 전장 이펙트
