// 🏷️ 마커 이름 라벨 겹침 방지 함수
// markers[] 배열의 모든 마커를 순회하여 픽셀 좌표 기반 AABB 충돌 감지 후 겹치는 라벨 숨김
function _applyMarkerLabelDeclutter() {
    if (!map || !markers || markers.length === 0) return;

    // 라벨 선택자 목록 (우선순위 높은 것부터 — capital 마커의 city-name이 먼저)
    const LABEL_SELECTORS = '.feature-name, .city-name, .city-marker-text';

    // 1단계: 모든 마커에서 (픽셀 좌표, 라벨 요소, 우선순위) 수집
    const entries = [];
    for (const m of markers) {
        const el = m.getElement && m.getElement();
        if (!el) continue;

        // 라벨 요소 탐색 (클래스 기반 + inline span 폴백)
        let labelEl = el.querySelector(LABEL_SELECTORS);
        if (!labelEl) {
            // PLACE_TYPE_CONFIG 스타일 — nameStyle inline span (마지막 span)
            const spans = el.querySelectorAll('span');
            if (spans.length > 0) labelEl = spans[spans.length - 1];
        }
        if (!labelEl) continue;

        // 라벨 가시성 초기화 (이전 declutter 결과 리셋)
        labelEl.style.visibility = '';

        const latlng = m.getLatLng();
        const pt = map.latLngToContainerPoint(latlng);

        // 라벨 크기 추정 (getBoundingClientRect가 더 정확하지만 레이아웃 비용↑)
        const text = labelEl.textContent || '';
        const estW = Math.max(text.length * 7, 20); // 한자/한글 평균 ~7px
        const estH = 14;

        // 수도 마커 우선순위: zIndexOffset 1000 이상 또는 isCapital 플래그
        const priority = (m.isCapital || (m.options && m.options.zIndexOffset >= 1000)) ? 0 : 1;

        entries.push({ pt, labelEl, estW, estH, priority, latlng });
    }

    // 2단계: 수도 우선으로 정렬 (priority 0이 먼저)
    entries.sort((a, b) => a.priority - b.priority);

    // 3단계: AABB 겹침 체크 — 이미 점유된 영역과 비교
    const occupied = []; // { x1, y1, x2, y2 }

    for (const entry of entries) {
        const { pt, labelEl, estW, estH, priority } = entry;

        // 라벨 AABB (라벨은 마커 아이콘 아래에 위치)
        const padding = 2; // 여유 간격
        const x1 = pt.x - estW / 2 - padding;
        const y1 = pt.y + 8 - padding; // 아이콘 높이 ~8px 아래부터 라벨 시작
        const x2 = pt.x + estW / 2 + padding;
        const y2 = y1 + estH + padding * 2;

        // 수도는 항상 표시
        if (priority === 0) {
            labelEl.style.visibility = '';
            occupied.push({ x1, y1, x2, y2 });
            continue;
        }

        // 겹침 체크
        let overlaps = false;
        for (const occ of occupied) {
            if (x1 < occ.x2 && x2 > occ.x1 && y1 < occ.y2 && y2 > occ.y1) {
                overlaps = true;
                break;
            }
        }

        if (overlaps) {
            labelEl.style.visibility = 'hidden';
        } else {
            labelEl.style.visibility = '';
            occupied.push({ x1, y1, x2, y2 });
        }
    }
}
window._applyMarkerLabelDeclutter = _applyMarkerLabelDeclutter;

// 🚀 [최적화] getCountryInfoById 캐시 — countries.find() 반복 호출 방지
let _countryLookupMap = null;
let _countryLookupVersion = 0; // countries 배열 변경 감지용

function _buildCountryLookup() {
    _countryLookupMap = new Map();
    countries.forEach(c => {
        if (!c) return;
        // _id 기반 조회 (문자열로 통일)
        if (c._id) {
            _countryLookupMap.set(String(c._id), c);
        }
        // 이름 기반 조회 (영토 데이터의 country_id가 문자열인 경우)
        if (c.name) _countryLookupMap.set(c.name, c);
        if (c.name_kor) _countryLookupMap.set(c.name_kor, c);
        if (c.name_eng) _countryLookupMap.set(c.name_eng, c);
        if (c.name_chi) _countryLookupMap.set(c.name_chi, c);
        (Array.isArray(c.aliases) ? c.aliases : String(c.aliases || '').split(/[,\n]/)).forEach(alias => {
            const cleanAlias = String(alias || '').trim();
            if (cleanAlias) _countryLookupMap.set(cleanAlias, c);
        });
        (Array.isArray(c.history) ? c.history : []).forEach(phase => {
            [phase.name, phase.name_zh, ...(Array.isArray(phase.aliases) ? phase.aliases : [])].forEach(alias => {
                const cleanAlias = String(alias || '').trim();
                if (cleanAlias) _countryLookupMap.set(cleanAlias, c);
            });
        });
    });
    _countryLookupVersion = countries.length;
}

function getEffectiveCountryInfo(country, year = null, month = null) {
    if (!country) return null;
    const mapYear = year ?? (Number.parseInt(document.getElementById('yearInput')?.value, 10) || 0);
    const mapMonth = month ?? (Number.parseInt(document.getElementById('monthInput')?.value, 10) || 1);
    const point = mapYear * 12 + Math.min(12, Math.max(1, mapMonth)) - 1;
    const phase = (Array.isArray(country.history) ? country.history : [])
        .filter(item => {
            const startYear = Number.parseInt(item.start_year ?? item.start, 10);
            if (!Number.isFinite(startYear)) return false;
            const start = startYear * 12 + (Number.parseInt(item.start_month, 10) || 1) - 1;
            const endYearValue = item.end_year ?? item.end;
            const endYear = endYearValue === null || endYearValue === undefined || endYearValue === ''
                ? null : Number.parseInt(endYearValue, 10);
            const end = Number.isFinite(endYear)
                ? endYear * 12 + (Number.parseInt(item.end_month, 10) || 12) - 1
                : Infinity;
            return point >= start && point <= end;
        })
        .sort((a, b) => (
            Number.parseInt(b.start_year ?? b.start, 10) - Number.parseInt(a.start_year ?? a.start, 10) ||
            (Number.parseInt(b.start_month, 10) || 1) - (Number.parseInt(a.start_month, 10) || 1)
        ))[0];
    if (!phase) return country;
    return {
        ...country,
        ...phase,
        _id: country._id,
        base_name: country.name,
        name: phase.name || country.name,
        name_zh: phase.name_zh || country.name_zh || country.name_chi || '',
        color: phase.color || country.color,
        flag: phase.flag || country.flag,
        sealText: phase.sealText || country.sealText,
        description: phase.description || country.description,
        aliases: [...new Set([...(country.aliases || []), ...(phase.aliases || [])])],
        active_country_phase: phase
    };
}

function getCountryInfoById(id, year = null, month = null) {
    if (!id) return null;

    // countries 배열이 변경되면 캐시 재구축
    if (!_countryLookupMap || _countryLookupVersion !== countries.length) {
        _buildCountryLookup();
    }

    const country = _countryLookupMap.get(String(id)) || null;
    return country ? getEffectiveCountryInfo(country, year, month) : null;
}

function getCountrySearchMatches(query, limit = 50) {
    const normalizedQuery = String(query || '').trim().toLowerCase();
    if (!normalizedQuery) return [];

    const matches = [];
    const addMatch = (country, phase, names) => {
        const cleanNames = [...new Set((names || []).map(name => String(name || '').trim()).filter(Boolean))];
        const matchedName = cleanNames.find(name => name.toLowerCase().includes(normalizedQuery));
        if (!matchedName) return;
        const displayName = String(phase?.name || country?.name || matchedName).trim();
        matches.push({ country, phase: phase || null, matchedName, displayName });
    };

    (countries || []).forEach(country => {
        if (!country) return;
        const aliases = Array.isArray(country.aliases)
            ? country.aliases : String(country.aliases || '').split(/[,\n]/);
        addMatch(country, null, [country.name, country.name_kor, country.name_eng, country.name_chi, country.name_zh, ...aliases]);
        (Array.isArray(country.history) ? country.history : []).forEach(phase => {
            const phaseAliases = Array.isArray(phase?.aliases)
                ? phase.aliases : String(phase?.aliases || '').split(/[,\n]/);
            addMatch(country, phase, [phase?.name, phase?.name_zh, ...phaseAliases]);
        });
    });

    return matches
        .sort((a, b) => {
            const aExact = a.matchedName.toLowerCase() === normalizedQuery ? 0 : 1;
            const bExact = b.matchedName.toLowerCase() === normalizedQuery ? 0 : 1;
            return aExact - bExact || a.displayName.localeCompare(b.displayName, 'ko');
        })
        .slice(0, limit);
}

function getExactCountrySearchMatch(value) {
    const normalizedValue = String(value || '').trim().toLowerCase();
    return getCountrySearchMatches(normalizedValue, Number.MAX_SAFE_INTEGER)
        .find(match => [match.displayName, match.matchedName]
            .some(name => String(name || '').trim().toLowerCase() === normalizedValue)) || null;
}

function getCountrySearchResultLabel(match) {
    const countryName = String(match?.country?.name || '').trim();
    const phaseName = String(match?.phase?.name || '').trim();
    const matchedName = String(match?.matchedName || '').trim();
    const period = match?.phase
        ? [match.phase.start_year ?? match.phase.start, match.phase.end_year ?? match.phase.end]
            .map(value => value === null || value === undefined || value === '' ? '현재' : `${value}년`)
            .join(' ~ ')
        : '';
    const aliasNote = matchedName && matchedName !== (phaseName || countryName) ? ` · 일치: ${matchedName}` : '';
    return match?.phase
        ? `${phaseName || matchedName} (${countryName}${period ? ` · ${period}` : ''}${aliasNote})`
        : `${countryName}${aliasNote}`;
}

// 🚩 [추가] 국가 정보 변경 시 캐시 강제 무효화
function invalidateCountryLookupCache() {
    _countryLookupMap = null;
    _countryLookupVersion = 0;
    // 🚩 [수정] localStorage 캐시도 함께 무효화 (페이지 새로고침 시 최신 데이터 로드)
    localStorage.removeItem('countries_cache');
    localStorage.removeItem('countries_cache_time');
    localStorage.removeItem('countries_cache_version');
}
    // --- 5. 데이터 로드 및 초기화 ---
    
    // 🚩 [추가] API 응답 에러 처리 함수
    function handleApiError(response, actionMsg) {
        // 🚩 [수정] 토큰 만료 시 게스트 상태라면 로그인 페이지로 보내지 않음
        if (response.status === 401 || response.status === 403) {
            console.warn('토큰이 만료되었습니다. 로그아웃합니다.');
            const msg = actionMsg
                ? `인증이 만료되어 [${actionMsg}] 작업을 완료할 수 없습니다.\n다시 로그인 후 재시도해 주세요.`
                : '인증이 만료되었습니다. 다시 로그인해 주세요.';
            const currentToken = localStorage.getItem('token') || sessionStorage.getItem('token');
            const payload = currentToken ? parseJwt(currentToken) : null;
            if (payload && payload.isGuest) {
                console.warn('게스트 인증 오류, 무시하고 계속 진행');
                return false;
            }
            alert(msg);
            localStorage.removeItem('token');
            localStorage.removeItem('username');
            localStorage.removeItem('role');
            window.location.href = 'login.html';
            return true; // 에러 처리됨
        }
        return false; // 에러 처리 안 됨
    }
    
    // 🚩 [추가] 토큰 가져오기 헬퍼 함수
    function getToken() {
        return localStorage.getItem('token') || sessionStorage.getItem('token');
    }
    
    // ⏱️ [성능] 브라우저 한가할 때 실행 (requestIdleCallback, timeout 2초)
    function defer(fn, timeout = 2000) {
        if ('requestIdleCallback' in window) {
            requestIdleCallback(fn, { timeout });
        } else {
            setTimeout(fn, 300);
        }
    }

    // 📦 [성능] TTL 캐시 확인 — 데이터 종류별 다른 TTL
    const _CACHE_TTL = {
        events:        10 * 60 * 1000,  // 10분
        contributions: 10 * 60 * 1000,  // 10분
        drawings:      30 * 60 * 1000,  // 30분
        naturalFeatures: 60 * 60 * 1000, // 60분
        kings:         60 * 60 * 1000,  // 60분
    };
    function isCacheStale(key) {
        const t = localStorage.getItem(key + '_fetchedAt');
        const ttl = _CACHE_TTL[key] || 30 * 60 * 1000;
        return !t || (Date.now() - parseInt(t)) > ttl;
    }
    function markCacheFresh(key) {
        localStorage.setItem(key + '_fetchedAt', Date.now().toString());
    }

    const KINGS_PAYLOAD_CACHE_KEY = 'kings_payload_cache_v2';
    function applyKingsPayload(data) {
        if (!Array.isArray(data)) return 0;
        kings = {};
        const kingKeysByCountry = new Map();
        data.forEach(item => {
            if (item.country_id && Array.isArray(item.kings)) {
                const countryId = String(item.country_id);
                if (!Array.isArray(kings[countryId])) kings[countryId] = [];
                if (!kingKeysByCountry.has(countryId)) kingKeysByCountry.set(countryId, new Set());
                const seen = kingKeysByCountry.get(countryId);

                item.kings.forEach(king => {
                    if (!king || typeof king !== 'object') return;
                    const kingId = king._id || king.person_id || king.source_ref_id;
                    const fallbackKey = [
                        king.name_ko || king.name || '',
                        king.start ?? king.start_year ?? '',
                        king.start_month ?? 1,
                        king.end ?? king.end_year ?? '',
                        king.end_month ?? 12
                    ].join('|');
                    const dedupeKey = kingId ? `id:${String(kingId)}` : `period:${fallbackKey}`;
                    if (seen.has(dedupeKey)) return;
                    seen.add(dedupeKey);
                    kings[countryId].push(king);
                });
            }
        });
        Object.values(kings).forEach(list => list.sort((a, b) => {
            const aStart = Number(a.start ?? a.start_year ?? 0);
            const bStart = Number(b.start ?? b.start_year ?? 0);
            if (aStart !== bStart) return aStart - bStart;
            return Number(a.start_month ?? 1) - Number(b.start_month ?? 1);
        }));
        return Object.values(kings).reduce((sum, list) => sum + list.length, 0);
    }
    function loadKingsPayloadCache() {
        try {
            const cached = JSON.parse(localStorage.getItem(KINGS_PAYLOAD_CACHE_KEY) || 'null');
            const hasKings = cached && Array.isArray(cached.data)
                && cached.data.some(item => Array.isArray(item?.kings) && item.kings.length > 0);
            if (hasKings) return cached;
            localStorage.removeItem(KINGS_PAYLOAD_CACHE_KEY);
            return null;
        } catch (error) {
            localStorage.removeItem(KINGS_PAYLOAD_CACHE_KEY);
            return null;
        }
    }
    function saveKingsPayloadCache(data) {
        try {
            localStorage.setItem(KINGS_PAYLOAD_CACHE_KEY, JSON.stringify({ at: Date.now(), data }));
        } catch (error) {
            console.warn('⚠️ 왕 데이터 캐시 저장 실패:', error.message);
        }
    }
    function invalidateKingsPayloadCache() {
        localStorage.removeItem(KINGS_PAYLOAD_CACHE_KEY);
        localStorage.removeItem('kings_fetchedAt');
    }

    // 🔊 [사운드] 마커 클릭 효과음 — 볼륨 0.5
    const _sfxCache = {};
    function playSfx(src) {
        try {
            const safeSrc = src.replace(/ /g, '%20'); // 경로 공백 인코딩
            const audio = _sfxCache[safeSrc] || new Audio(safeSrc);
            audio.volume = 0.5;
            _sfxCache[safeSrc] = audio;
            audio.currentTime = 0;
            const p = audio.play();
            if (p && typeof p.catch === 'function') {
                p.catch(() => {
                    // 재생 실패 시 새 인스턴스로 재시도
                    const fresh = new Audio(safeSrc);
                    fresh.volume = 0.5;
                    _sfxCache[safeSrc] = fresh;
                    fresh.play().catch(err => console.warn('[SFX] 재생 실패:', safeSrc, err.message));
                });
            }
        } catch(e) { console.warn('[SFX] 예외:', e); }
    }
    // 사운드 파일 미리 load (재생 없이 버퍼링만 — Autoplay 정책 우회, 즉시 실행)
    ['/public/sound%20effect/War.m4a', '/public/sound%20effect/militery.m4a'].forEach(src => {
        const a = new Audio(src);
        a.volume = 0.5;
        a.preload = 'auto';
        a.load();
        _sfxCache[src] = a;
    });

    async function fetchData(endpoint) {
      try {
        // console.log(`📡 [Fetch] ${endpoint} 요청 시작...`);
        
        // 🚀 [최적화] countries 데이터 캐싱 (localStorage) — stale-while-revalidate
        if (endpoint === 'countries') {
            const cachedData = localStorage.getItem('countries_cache');
            const cacheTime = localStorage.getItem('countries_cache_time');
            const cacheVersion = localStorage.getItem('countries_cache_version');
            const CACHE_DURATION = 5 * 60 * 1000; // 5분
            const versionKey = localStorage.getItem('app_version') || 'init';
            
            if (cachedData && cacheTime && cacheVersion === versionKey) {
                const age = Date.now() - parseInt(cacheTime);
                if (age < CACHE_DURATION) {
                    // 캐시 유효: 즉시 반환하되, 백그라운드에서 최신 데이터 확인 (국가 추가/삭제 반영)
                    const cached = sanitizeCountryFlags(JSON.parse(cachedData));
                    // � [백그라운드 재검증] 서버와 개수 다르면 캐시 갱신 + 지도 재렌더링
                    setTimeout(async () => {
                        try {
                            const res = await fetch(`${API_BASE_URL}/countries`, {
                                headers: { 'Authorization': `Bearer ${token}` }
                            });
                            if (res.ok) {
                                const fresh = sanitizeCountryFlags(await res.json());
                                const cachedCount = cached.length;
                                const freshCount = fresh.length;
                                // 🚩 [수정] 개수 변경 OR 국기/색상/이름 변경 감지
                                const _fingerprint = arr => arr.map(c => `${c._id}|${c.flag||''}|${c.color||''}|${c.name||''}|${JSON.stringify(c.history||[])}|${JSON.stringify(c.predecessor_relations||[])}`).sort().join(',');
                                const changed = freshCount !== cachedCount || _fingerprint(fresh) !== _fingerprint(cached);
                                if (changed) {
                                    console.log(`🔄 [백그라운드] countries 변경 감지 (개수:${cachedCount}→${freshCount} 또는 국기/색상 변경). 캐시 갱신 및 지도 재렌더링`);
                                    localStorage.setItem('countries_cache', JSON.stringify(fresh));
                                    localStorage.setItem('countries_cache_time', Date.now().toString());
                                    localStorage.setItem('countries_cache_version', versionKey);
                                    countries = fresh;
                                    _countryLookupMap = null;
                                    if (updateMap._loggedMissingIds) updateMap._loggedMissingIds.clear();
                                    requestUpdateMap();
                                    // 🔑 [추가] 국가 필터 드롭다운도 갱신
                                    if (typeof window._fillCountryFilterSelect === 'function') window._fillCountryFilterSelect();
                                }
                            }
                        } catch(e) { /* 백그라운드 실패는 무시 */ }
                    }, 500);
                    return cached;
                }
            }
        }
        
        const requestData = () => fetch(`${API_BASE_URL}/${endpoint}`, {
            headers: { 'Authorization': `Bearer ${token}` },
            cache: endpoint === 'drawings' ? 'no-store' : 'default'
        });
        let response = await requestData();
        // 강/도형 데이터는 서버리스 DB 연결이 순간적으로 실패해도 빈 배열로
        // 기존 캐시를 덮어쓰지 않도록 한 번 재시도한다.
        if (endpoint === 'drawings' && response.status >= 500) {
            await new Promise(resolve => setTimeout(resolve, 800));
            response = await requestData();
        }
        
        // 🚩 [수정] 토큰 만료 시 게스트라면 login.html로 보내지 않음
        if (response.status === 401 || response.status === 403) {
            console.warn('토큰이 만료되었습니다. 로그아웃합니다.');
            const currentToken = localStorage.getItem('token') || sessionStorage.getItem('token');
            const payload = currentToken ? parseJwt(currentToken) : null;
            if (payload && payload.isGuest) {
                console.warn('게스트 인증 오류, 무시하고 계속 진행');
                return endpoint === 'drawings' ? null : [];
            }
            // alert 제거 - 세션이 거의 만료되지 않으므로 불필요
            localStorage.removeItem('token');
            localStorage.removeItem('username');
            localStorage.removeItem('role');
            window.location.href = 'login.html';
            return [];
        }
        
        if (!response.ok) {
          throw new Error(`${endpoint} 데이터 로드 실패: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        // console.log(`✅ [Fetch] ${endpoint} 완료 (${data.length || 0}개)`);
        
        // 🚀 [최적화] countries 데이터 캐싱 저장
        if (endpoint === 'countries') {
            const versionKey = localStorage.getItem('app_version') || 'init';
            localStorage.setItem('countries_cache', JSON.stringify(sanitizeCountryFlags(data)));
            localStorage.setItem('countries_cache_time', Date.now().toString());
            localStorage.setItem('countries_cache_version', versionKey);
            // console.log('💾 [캐시] countries 데이터 저장 완료');
        }
        
        return data;
      } catch (error) {
        console.error(`❌ [Fetch] ${endpoint} 오류:`, error);
        
        // 🚀 [최적화] 오류 시 캐시 데이터 사용 (countries)
        if (endpoint === 'countries') {
            const cachedData = localStorage.getItem('countries_cache');
            if (cachedData) {
                // console.log('💾 [캐시] 오류 발생, countries 캐시 데이터 사용');
                return sanitizeCountryFlags(JSON.parse(cachedData));
            }
        }
        
        // drawings 실패를 []로 반환하면 호출부가 정상 캐시를 빈 배열로 덮어쓴다.
        return endpoint === 'drawings' ? null : [];
      }
    }

    const BROWSER_PANEL_CONFIG_KEY = 'kh_panel_configuration_v1';
    const BROWSER_PANEL_KEYS = [
        'timeline', 'kingPanel', 'historyPanel', 'rankingPanel', 'activityFeed',
        'captionPanel', 'eventSidebar', 'drawingPanel', 'heatmap'
    ];
    function readBrowserPanelConfiguration() {
        try {
            const saved = JSON.parse(localStorage.getItem(BROWSER_PANEL_CONFIG_KEY) || 'null');
            return saved && typeof saved === 'object' ? saved : {};
        } catch (_) {
            return {};
        }
    }
    function persistBrowserPanelConfiguration() {
        const saved = {};
        BROWSER_PANEL_KEYS.forEach(key => { saved[key] = layerVisibility[key] === true; });
        try { localStorage.setItem(BROWSER_PANEL_CONFIG_KEY, JSON.stringify(saved)); } catch (_) {}
    }
    function withBrowserPanelConfiguration(settings) {
        // 사관 랭킹은 저장된 브라우저 설정이나 서버 설정과 관계없이
        // 매 페이지 최초 진입 시 닫힌 상태로 시작한다. 이후 메뉴에서 다시 켤 수 있다.
        return { ...(settings || {}), ...readBrowserPanelConfiguration(), rankingPanel:false };
    }

    // 🚩 [최적화] 레이어 설정 먼저 로드 (데이터 로딩 전)
    async function loadLayerSettings() {
        // console.log('🚀 [1단계] 레이어 설정 우선 로드...');
        const cacheKey = 'layer_settings_cache_v1';
        const cachedRaw = localStorage.getItem(cacheKey);
        if (cachedRaw) {
            try {
                const cachedSettings = withBrowserPanelConfiguration(JSON.parse(cachedRaw));
                Object.assign(layerVisibility, cachedSettings);
                applyLayerSettingsToUI(cachedSettings);

                // 첫 화면을 차단하지 않고 서버 설정을 재검증한다.
                fetch(`${API_BASE_URL}/layer-settings`)
                    .then(response => response.ok ? response.json() : null)
                    .then(data => {
                        if (!data || !data.settings) return;
                        localStorage.setItem(cacheKey, JSON.stringify(data.settings));
                        const mergedSettings = withBrowserPanelConfiguration(data.settings);
                        Object.assign(layerVisibility, mergedSettings);
                        applyLayerSettingsToUI(mergedSettings);
                    })
                    .catch(() => {});
                console.log('⚡ 레이어 설정 캐시 즉시 적용');
                return cachedSettings;
            } catch (error) {
                localStorage.removeItem(cacheKey);
            }
        }

        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 1500);
            const response = await fetch(`${API_BASE_URL}/layer-settings`, { signal: controller.signal });
            clearTimeout(timeoutId);
            if (!response.ok) {
                // console.log('⚠️ 레이어 설정을 불러올 수 없어 기본값을 사용합니다.');
                return null;
            }

            const data = await response.json();
            const settings = withBrowserPanelConfiguration(data.settings);
            localStorage.setItem(cacheKey, JSON.stringify(settings));
            // console.log('✅ 레이어 설정 로드 성공:', settings);
            
            // layerVisibility 객체 업데이트
            Object.assign(layerVisibility, settings);

            // 🚩 kingPanel / historyPanel: 설정값에 따라 패널 DOM 즉시 반영
            const kingPanel = document.getElementById('map-king-panel');
            const historyPanel = document.getElementById('map-history-panel');
            // 📱 모바일에서는 왕패널 항상 숨김
            const mobileLayout = document.body.classList.contains('force-mobile') || window.innerWidth <= 967 || window.innerHeight > window.innerWidth;
            const kingPanelVisible = !mobileLayout && layerVisibility.kingPanel;
            if (mobileLayout) layerVisibility.kingPanel = false;
            if (kingPanel) setKingPanelVisibility(kingPanelVisible);
            setHistoryPanelVisibility(layerVisibility.historyPanel);

            // 🚩 햄버거 메뉴 체크박스 동기화 (DOMContentLoaded보다 늦게 완료되므로 여기서 재적용)
            const layerCheckboxMap = {
                'menu-layer-city': 'city',
                'menu-layer-territory': 'territoryPolygon',
                'menu-layer-country-label': 'countryLabel',
                'menu-layer-admin-label': 'adminLabel',
                'menu-layer-place-label': 'placeLabel',
                'menu-layer-ethnic-label': 'ethnicLabel',
                'menu-layer-military': 'military',
                'menu-layer-natural': 'natural',
                'menu-layer-relic': 'relic',
                'menu-layer-rivers': 'rivers',
                'menu-layer-water-level': 'waterLevel',
                'menu-layer-event': 'event',
                'menu-layer-timeline': 'timeline',
                'menu-layer-king': 'kingPanel',
                'menu-layer-history': 'historyPanel',
                'menu-layer-contributions': 'userContributions',
                'menu-layer-ranking': 'rankingPanel',
                'menu-layer-activity-feed': 'activityFeed',
                'menu-layer-caption': 'captionPanel'
            };
            Object.entries(layerCheckboxMap).forEach(([cbId, layerKey]) => {
                const cb = document.getElementById(cbId);
                if (cb) cb.checked = layerVisibility[layerKey] === true;
            });
            
            return settings;
        } catch (error) {
            console.error('❌ 레이어 설정 로드 실패:', error);
            return null;
        }
    }

    // 🚩 [추가] 레이어 설정 UI 적용 (데이터 로딩 후)
    function applyLayerSettingsToUI(settings) {
        if (!settings) return;
        
        // console.log('🎨 레이어 설정 UI 적용 중...');
        
        // 레이어 토글 버튼들의 초기 상태 설정
        Object.entries(settings).forEach(([layerKey, isEnabled]) => {
            const button = document.querySelector(`.layer-toggle-btn[data-layer="${layerKey}"]`);
            if (button) {
                if (isEnabled) {
                    button.classList.add('active');
                } else {
                    button.classList.remove('active');
                }
            }
        });

        // 모바일 레이어 체크박스들도 업데이트
        const mobileCheckboxes = document.querySelectorAll('#mobile-layer-menu input[type="checkbox"]');
        mobileCheckboxes.forEach(checkbox => {
            const layerKey = checkbox.dataset.layer;
            if (settings.hasOwnProperty(layerKey)) {
                checkbox.checked = settings[layerKey];
            }
        });
        if (Object.prototype.hasOwnProperty.call(settings, 'historyPanel')) {
            setHistoryPanelVisibility(settings.historyPanel === true);
        }
        if (Object.prototype.hasOwnProperty.call(settings, 'kingPanel')) {
            setKingPanelVisibility(settings.kingPanel === true);
        }
        if (Object.prototype.hasOwnProperty.call(settings, 'timeline')) {
            setTimelinePanelVisibility(settings.timeline === true, { rebuild:false });
        }
        if (Object.prototype.hasOwnProperty.call(settings, 'captionPanel')
            && typeof toggleHistoryCaption === 'function') {
            toggleHistoryCaption(settings.captionPanel === true);
        }
        const simplePanels = {
            rankingPanel:'rankingDisplay', activityFeed:'activity-feed-panel'
        };
        Object.entries(simplePanels).forEach(([key, id]) => {
            if (!Object.prototype.hasOwnProperty.call(settings, key)) return;
            const element = document.getElementById(id);
            if (element) element.style.display = settings[key] === true ? '' : 'none';
        });
        
        // console.log('✅ 레이어 설정 UI 적용 완료');
    }

    function setHistoryPanelVisibility(visible) {
        const panel = document.getElementById('map-history-panel');
        if (!panel) return;
        const mobile = document.body.classList.contains('force-mobile') || window.innerWidth <= 967 || window.innerHeight > window.innerWidth;
        panel.style.setProperty('display', visible ? 'flex' : 'none', 'important');
        panel.style.pointerEvents = visible ? 'auto' : 'none';
        document.body.classList.toggle('history-panel-open', visible && mobile);
        // 축소형 플로팅 버튼은 사용하지 않으므로 켤 때는 항상 전체 패널로 연다.
        if (visible) panel.classList.add('expanded');
        if (!visible && mobile) panel.classList.remove('expanded');
        if (visible) window.bringAppPanelToFront?.(panel);
        else window.releaseAppPanel?.(panel);
        if (!visible && window._historyOpenedFromHeroDetail) {
            document.getElementById('heroIllustWrap')?.classList.remove('open');
            window._historyOpenedFromHeroDetail = false;
        }
        if (!visible) {
            panel.classList.remove('history-linked-focus');
            panel.style.removeProperty('z-index');
            document.querySelectorAll('.history-search-target').forEach(element => {
                element.classList.remove('history-search-target');
                element.removeAttribute('aria-current');
            });
            window._historyRecordFocusRequest = null;
        }
    }

    // 모든 주요 패널은 마지막으로 연/선택한 순서대로 전면에 쌓인다.
    let appPanelStackOrder = 200000;
    let appTopPanel = null;
    const appPanelStack = [];
    window.bringAppPanelToFront = function(panelOrId, options = {}) {
        const panel = typeof panelOrId === 'string' ? document.getElementById(panelOrId) : panelOrId;
        if (!panel) return;
        const isPriorityOverlay = panel.id === 'newsletter-popup-overlay';
        // 일반 역사 패널은 다른 상세 패널의 뒤에 두되, 전체화면 모드에서는
        // 사용 목적대로 왕목록을 포함한 다른 패널보다 전면에 올린다.
        const isBackgroundHistoryPanel = panel.id === 'map-history-panel'
            && !panel.classList.contains('history-window-fullscreen');
        appPanelStackOrder += 10;
        const behind = Array.isArray(options.behind) ? options.behind.filter(Boolean) : [];
        behind.forEach((element, index) => {
            element.style.setProperty('z-index', String(appPanelStackOrder + index + 1), 'important');
        });
        panel.style.setProperty(
            'z-index',
            isPriorityOverlay
                ? '2147483000'
                : isBackgroundHistoryPanel
                    ? '160100'
                    : String(appPanelStackOrder + behind.length + 2),
            'important'
        );
        const previousIndex = appPanelStack.indexOf(panel);
        if (previousIndex >= 0) appPanelStack.splice(previousIndex, 1);
        appPanelStack.push(panel);
        appTopPanel = panel;
        window._appTopPanel = panel;
        const mobile = document.body.classList.contains('force-mobile') || window.innerWidth <= 967 || window.innerHeight > window.innerWidth;
        if (mobile && options.keepTimeControls !== false) {
            ['timeline-play-controls', 'map-tile-toggle-group', 'timeline-control', 'timeline-container'].forEach(id => {
                document.getElementById(id)?.style.setProperty('z-index', String(appPanelStackOrder + behind.length + 3), 'important');
            });
        }
    };
    window.isAppPanelOnTop = function(panelOrId) {
        const panel = typeof panelOrId === 'string' ? document.getElementById(panelOrId) : panelOrId;
        return !!panel && appTopPanel === panel;
    };
    window.releaseAppPanel = function(panelOrId) {
        const panel = typeof panelOrId === 'string' ? document.getElementById(panelOrId) : panelOrId;
        if (!panel) return;
        const index = appPanelStack.indexOf(panel);
        if (index >= 0) appPanelStack.splice(index, 1);
        appTopPanel = appPanelStack[appPanelStack.length - 1] || null;
        window._appTopPanel = appTopPanel;
    };
    if (!window.__appPanelPointerStackBound) {
        window.__appPanelPointerStackBound = true;
        document.addEventListener('pointerdown', event => {
            const panel = event.target.closest?.('#map-history-panel, #map-king-panel, #timeline-sidebar, #hamburger-menu-panel, #object-detail-panel, #country-detail-panel, #heroSidebar, #heroIllustWrap, #mobile-search-overlay, #coordGotoBox, #newsletter-popup-overlay');
            if (!panel) return;
            if (panel.id === 'heroIllustWrap' || panel.id === 'heroSidebar') {
                window.bringAppPanelToFront?.(document.getElementById('heroSidebar'), { behind:[document.getElementById('heroIllustWrap')] });
            } else {
                window.bringAppPanelToFront?.(panel, { keepTimeControls: !['mobile-search-overlay', 'coordGotoBox', 'newsletter-popup-overlay'].includes(panel.id) });
            }
        }, true);
    }

    // 역사↔인물 링크도 동일한 공통 패널 스택을 사용한다.
    window.bringLinkedDetailPanelToFront = function(panelType) {
        const historyPanel = document.getElementById('map-history-panel');
        const heroSidebar = document.getElementById('heroSidebar');
        const heroIllustration = document.getElementById('heroIllustWrap');
        if (panelType === 'history') {
            window.bringAppPanelToFront(historyPanel);
            return;
        }
        if (panelType === 'person') {
            window.bringAppPanelToFront(heroSidebar, { behind:[heroIllustration] });
        }
    };

    // 모바일에서는 패널을 겹쳐 쌓지 않고 상세 화면처럼 하나씩 전환한다.
    window.prepareMobilePanelTransition = function(target) {
        const mobile = document.body.classList.contains('force-mobile') || window.innerWidth <= 967 || window.innerHeight > window.innerWidth;
        if (!mobile) return false;
        if (target !== 'history') setHistoryPanelVisibility(false);
        if (target !== 'object') closeDetailPanel();
        if (target !== 'country') window.closeCountryPanel?.();
        if (target !== 'person') window.heroSystem?.closeSidebar?.();
        if (target !== 'king') setKingPanelVisibility(false);
        document.getElementById('timeline-sidebar')?.classList.remove('open', 'active');
        document.body.classList.remove('timeline-panel-open');
        return true;
    };

    function setKingPanelVisibility(visible) {
        const panel = document.getElementById('map-king-panel');
        if (!panel) return;
        const mobile = document.body.classList.contains('force-mobile') || window.innerWidth <= 967 || window.innerHeight > window.innerWidth;
        panel.style.setProperty('display', visible ? (mobile ? 'flex' : 'block') : 'none', 'important');
        panel.style.pointerEvents = visible ? 'auto' : 'none';
        panel.classList.toggle('mobile-fullscreen', visible && mobile);
        document.body.classList.toggle('king-panel-open', visible && mobile);
        if (visible) window.bringAppPanelToFront?.(panel);
        else window.releaseAppPanel?.(panel);
        if (visible && !mobile) positionKingPanelBelowRanking();
    }

    function canAdminEditHistoryRecords() {
        return !!(editMode && (currentUser?.role === 'admin' || currentUser?.role === 'superuser'));
    }

    // 🚩 [기존] 레이어 기본 설정 불러오기 및 적용 (하위 호환성)
    async function loadAndApplyLayerSettings() {
        // console.log('🚀 loadAndApplyLayerSettings 함수 시작');
        try {
            // console.log('🔄 레이어 설정 불러오기 시작...');
            const response = await fetch(`${API_BASE_URL}/layer-settings`);
            // console.log('📡 API 응답 상태:', response.status);
            if (!response.ok) {
                // console.log('⚠️ 레이어 설정을 불러올 수 없어 기본값을 사용합니다.');
                return;
            }

            const data = await response.json();
            const settings = data.settings;
            // console.log('✅ 레이어 설정 불러오기 성공:', settings);

            // 🚀 [최적화] 레이어 일괄 업데이트 - 한 번의 렌더링 사이클로 처리
            let needsMapUpdate = false;
            const layersToUpdate = [];

            // 레이어 토글 버튼들의 초기 상태 설정 및 레이어 표시/숨김 적용
            Object.entries(settings).forEach(([layerKey, isEnabled]) => {
                // layerVisibility는 버튼 유무와 무관하게 항상 업데이트
                layerVisibility[layerKey] = isEnabled;

                // 토글 버튼 활성화 표시
                const button = document.querySelector(`.layer-toggle-btn[data-layer="${layerKey}"]`);
                if (button) {
                    if (isEnabled) button.classList.add('active');
                    else button.classList.remove('active');
                }

                // UI 전용 레이어 처리 (버튼 유무와 무관)
                if (layerKey === 'timeline') {
                    setTimelineLayerVisible(isEnabled, { rebuild: isEnabled });
                } else if (layerKey === 'kingPanel') {
                    setKingPanelVisibility(isEnabled);
                } else if (layerKey === 'historyPanel') {
                    setHistoryPanelVisibility(isEnabled);
                    // 패널을 켤 때 현재 연도의 기록 즉시 로드
                    if (isEnabled) {
                        const { year } = getCurrentYearMonth();
                        updateHistoryPanel(year);
                    }
                } else if (layerKey === 'rankingPanel') {
                    const el = document.getElementById('rankingDisplay');
                    if (el) el.style.display = isEnabled ? '' : 'none';
                } else if (layerKey === 'activityFeed') {
                    const el = document.getElementById('activity-feed-panel');
                    if (el) el.style.display = isEnabled ? '' : 'none';
                } else if (layerKey === 'captionPanel') {
                    if (typeof toggleHistoryCaption === 'function') toggleHistoryCaption(isEnabled);
                    if (isEnabled) {
                        // 자막 즉시 갱신
                        const { year } = getCurrentYearMonth();
                        updateHistoryPanel(year);
                    }
                } else if (layerKey === 'eventSidebar') {
                    const eventSidebar = document.getElementById('event-sidebar');
                    if (eventSidebar) {
                        if (isEnabled) {
                            eventSidebar.classList.add('open');
                            if (typeof renderEventSidebar === 'function') renderEventSidebar();
                        } else {
                            eventSidebar.classList.remove('open');
                        }
                    }
                } else {
                    // 맵 레이어 업데이트 필요
                    needsMapUpdate = true;
                    layersToUpdate.push(layerKey);
                }
            });

            // 🚀 [최적화] 모든 맵 레이어를 한 번에 업데이트
            if (needsMapUpdate) {
                const { year, month } = getCurrentYearMonth();
                updateMap(year, month);
                console.log(`🗺️ 일괄 맵 레이어 업데이트 (${layersToUpdate.length}개):`, layersToUpdate.join(', '));
            }

            // 모바일 레이어 체크박스들도 업데이트
            const mobileCheckboxes = document.querySelectorAll('#mobile-layer-menu input[type="checkbox"]');
            mobileCheckboxes.forEach(checkbox => {
                const layerKey = checkbox.dataset.layer;
                if (settings.hasOwnProperty(layerKey)) {
                    checkbox.checked = settings[layerKey];
                }
            });

            // 📱 모바일에서는 서버 설정과 무관하게 왕패널 항상 숨김
            if (document.body.classList.contains('force-mobile') || window.innerWidth <= 967 || window.innerHeight > window.innerWidth) {
                layerVisibility.kingPanel = false;
                setKingPanelVisibility(false);
                const kingCb = document.querySelector('#mobile-layer-menu input[data-layer="kingPanel"]');
                if (kingCb) kingCb.checked = false;
            }

            console.log('🎉 레이어 설정 적용 완료');
        } catch (error) {
            console.error('❌ 레이어 설정 불러오기 실패:', error);
            // 실패 시 기본값 유지
        }
    }

