    // �️ [방어코드] drawings 배열의 _id를 항상 string으로 정규화
    // MongoDB ObjectId 객체({$oid: '...'})나 toString() 가능한 객체 모두 처리
    function normalizeDrawings(data) {
        if (!Array.isArray(data)) return [];
        return data.map(d => {
            if (!d) return d;
            const id = d._id?.$oid ?? (typeof d._id === 'object' && d._id !== null ? d._id.toString() : d._id);
            return { ...d, _id: id };
        });
    }

