    // ✂️ 선분 지우기 저장
    document.getElementById('segmentEraseSaveBtn').addEventListener('click', async () => {
        const d = window._segmentEraseDrawing;
        if (!d) return;

        // _segmentEraseSet에 누적된 인덱스들을 한 번에 geom에서 제거
        const geom = d.geojson?.geometry || d.geojson;
        if (geom && geom.type === 'MultiLineString' && window._segmentEraseSet?.size > 0) {
            geom.coordinates = geom.coordinates.filter((_, idx) => !window._segmentEraseSet.has(idx));
        }

        const id = d._id?.$oid || d._id?.toString?.() || d._id;
        // 이 플래그로 updateDrawingInMemory의 서버 재fetch + updateMap 호출을 막음
        window._eraserJustSaved = id;
        window._eraserSavedAt = Date.now(); // 저장 시각 기록
        const token = localStorage.getItem('token') || sessionStorage.getItem('token') || '';
        try {
            const r = await fetch(`/api/drawings/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
                body: JSON.stringify({ geojson: d.geojson })
            });
            if (!r.ok) throw new Error('저장 실패');

            // 클로저 drawings 배열에서 해당 항목의 geojson 직접 교체
            const memIdx = drawings.findIndex(x => {
                const xid = x._id?.$oid || x._id?.toString?.() || x._id;
                return String(xid) === String(id);
            });
            if (memIdx !== -1) {
                drawings[memIdx].geojson = JSON.parse(JSON.stringify(d.geojson));
                console.log('✅ 지우개 저장 — drawings 메모리 반영:', id, '남은 선분:', drawings[memIdx].geojson?.geometry?.coordinates?.length ?? drawings[memIdx].geojson?.coordinates?.length);
                // IndexedDB 캐시도 갱신
                if (typeof saveDrawingsCache === 'function') {
                    saveDrawingsCache(drawings).catch(() => {});
                }
            } else {
                console.warn('⚠️ drawings에서 찾지 못함:', id);
            }

            showToast('✅ 선분 삭제 저장 완료', 'success');
            window._segmentEraseMode = false;
            window._segmentEraseDrawing = null;
            window._segmentEraseSet = null;
            window._eraserMouseDown = false;
            map.dragging.enable();
            document.getElementById('segmentEraseHint').style.display = 'none';
            document.getElementById('segmentEraseBtn').textContent = '🧹 선분 지우기 모드';
            document.getElementById('segmentEraseBtn').style.background = 'rgba(180,80,20,0.15)';
            map.getContainer().style.cursor = '';
            document.getElementById('drawingForm').style.display = 'none';
        } catch(e) {
            showToast('❌ 저장 중 오류: ' + e.message, 'error');
        }
    });

