        // ── 📡 [SessionCache] 데이터 버전 폴링 — 변경 시 자동 동기화 ────────
        (function _startVersionPolling() {
            const POLL_INTERVAL_MS = 60 * 1000;
            let _refreshing = false;

            async function _syncIfChanged() {
                if (_refreshing || document.hidden) return;
                try {
                    const res = await fetch('/api/castle/version', { cache: 'no-store' });
                    if (!res.ok) return;
                    const data = await res.json();
                    const latestVersion = String(data.lastModified || '');
                    const sessionVersion = window._sessionMapCache.sessionDataVersion;
                    if (latestVersion && sessionVersion && latestVersion !== sessionVersion) {
                        _refreshing = true;
                        const isDev = (location.hostname === 'localhost' || location.hostname === '127.0.0.1');
                        if (isDev) console.debug(`[SessionCache] version drift detected: session=${sessionVersion} server=${latestVersion}`);
                        const freshRes = await fetch(`${API_BASE_URL}/castle`, {
                            headers: {
                                'Authorization': `Bearer ${getToken()}`,
                                'X-Force-Refresh': '1'
                            },
                            cache: 'no-store'
                        });
                        if (!freshRes.ok) throw new Error(`castle 자동 갱신 실패 (${freshRes.status})`);
                        const freshCastles = await freshRes.json();
                        _initCastlesSession(freshCastles);
                        await saveCastlesCache(freshCastles);
                        window._sessionMapCache.sessionDataVersion = latestVersion;
                        _dominantCountryCache.clear();
                        _activeCastleTerritoryCache.clear();
                        _activeCastleTerritoryCacheKey = '';
                        lastUpdateMapCall = { year:null, month:null, cacheOnly:null, dataFingerprint:null };
                        requestUpdateMap(true);
                        if (typeof showToast === 'function') {
                            showToast('🔄 최신 지도 데이터가 자동 반영되었습니다.', 'success');
                        }
                    }
                } catch (e) {
                    console.warn('⚠️ 최신 데이터 자동 동기화 실패:', e.message);
                } finally {
                    _refreshing = false;
                }
            }

            setInterval(_syncIfChanged, POLL_INTERVAL_MS);
            document.addEventListener('visibilitychange', () => {
                if (!document.hidden) _syncIfChanged();
            });
        })();

        // ===== 🚩 [재생 버튼] 사이클 속도 버튼 설정 (▶→▶▶→▶▶▶→▶▶▶▶→▶) =====
        function _cyclePlayback() {
            playbackMode = (playbackMode + 1) % 4;
            updatePlaybackButtonLabel();
            if (playbackMode === 0) {
                stopPlayback();
            } else if (playbackMode === 1) {
                startPlayback();
            }
            // 모드 2, 3: 타이머 유지, 틱에서 stepMonths만 바뀜
        }
        function _stopPlaybackBtn() {
            playbackMode = 0;
            updatePlaybackButtonLabel();
            stopPlayback();
        }

        playBtn.onclick = null;
        playBtn.addEventListener('click', _cyclePlayback);
        pauseBtn.onclick = null;
        pauseBtn.addEventListener('click', _stopPlaybackBtn);

        // timelinePlayBtn: cycling (PC에서 보이는 버튼)
        const _tPlayBtn = document.getElementById('timelinePlayBtn');
        const _tPauseBtn = document.getElementById('timelinePauseBtn');
        if (_tPlayBtn) {
            _tPlayBtn.onclick = null;
            _tPlayBtn.addEventListener('click', _cyclePlayback);
            _tPlayBtn.textContent = PLAYBACK_LABELS[0];
            _tPlayBtn.title = PLAYBACK_TITLES[0];
        }
        if (_tPauseBtn) {
            _tPauseBtn.onclick = null;
            _tPauseBtn.addEventListener('click', _stopPlaybackBtn);
        }
        playBtn.textContent = PLAYBACK_LABELS[0];
        playBtn.title = PLAYBACK_TITLES[0];

        // ===== 🚩 [슬라이더 핸들러] rAF 기반 실시간 업데이트 =====
        combinedSlider.addEventListener('input', () => {
            const compactizeTimeLabels = () => {
                try { timeLabelDisplay?.classList.add('compact'); } catch(e){}
                try { document.getElementById('timeLabelDisplay-pc')?.classList.add('compact'); } catch(e){}
                try { document.getElementById('current-year-display')?.classList.add('compact'); } catch(e){}
            };
            compactizeTimeLabels();
            const totalMonths = parseInt(combinedSlider.value);
            const { year, month } = totalMonthsToYearMonth(totalMonths);
            updateUI(year, month);
            updateSliderTooltip(year, month);
            _sliderPendingYear = year;
            _sliderPendingMonth = month;
            if (!_sliderRAF) {
                _sliderRAF = requestAnimationFrame(() => {
                    _sliderRAF = null;
                    if (_sliderLastMapYear === _sliderPendingYear && _sliderLastMapMonth === _sliderPendingMonth) return;
                    _sliderLastMapYear = _sliderPendingYear;
                    _sliderLastMapMonth = _sliderPendingMonth;
                    updateMap(_sliderLastMapYear, _sliderLastMapMonth);
                    if (typeof refreshWaterLevelOverlay === 'function') refreshWaterLevelOverlay(_sliderLastMapYear);
                    refreshHeroPinsForTime(_sliderLastMapYear, _sliderLastMapMonth, false);
                    window._refreshCountryLineageForTime?.();
                });
            }
        });
        const _removeCompactLabels = () => {
            try { timeLabelDisplay?.classList.remove('compact'); } catch(e){}
            try { document.getElementById('timeLabelDisplay-pc')?.classList.remove('compact'); } catch(e){}
            try { document.getElementById('current-year-display')?.classList.remove('compact'); } catch(e){}
            document.body.classList.remove('slider-dragging');
            if (_sliderRAF) { cancelAnimationFrame(_sliderRAF); _sliderRAF = null; }
            if (_sliderPendingYear !== null) {
                updateMap(_sliderPendingYear, _sliderPendingMonth, false, true);
                if (typeof refreshWaterLevelOverlay === 'function') refreshWaterLevelOverlay(_sliderPendingYear, true);
                refreshHeroPinsForTime(_sliderPendingYear, _sliderPendingMonth, false);
                checkAndDisplayEvent(_sliderPendingYear, _sliderPendingMonth);
                scheduleHistoryPanelUpdate(_sliderPendingYear);
                _sliderLastMapYear = _sliderPendingYear;
                _sliderLastMapMonth = _sliderPendingMonth;
                _sliderPendingYear = null;
                _sliderPendingMonth = null;
            }
        };
        combinedSlider.addEventListener('change', _removeCompactLabels);
        combinedSlider.addEventListener('mouseup', _removeCompactLabels);
        combinedSlider.addEventListener('touchend', _removeCompactLabels);

        // 슬라이더 조작 시 재생 정지 (playbackMode 리셋)
        combinedSlider.addEventListener('mousedown', () => { document.body.classList.add('slider-dragging'); playbackMode = 0; updatePlaybackButtonLabel(); stopPlayback(); });
        combinedSlider.addEventListener('touchstart', () => { document.body.classList.add('slider-dragging'); playbackMode = 0; updatePlaybackButtonLabel(); stopPlayback(); });

        // 초기 슬라이더 툴팁
        const _initTotalMonths = parseInt(combinedSlider.value);
        const { year: _initYear, month: _initMonth } = totalMonthsToYearMonth(_initTotalMonths);
        updateSliderTooltip(_initYear, _initMonth);

        initializeTopPanelToggle(); // 🚩 [추가] PC 버전 상단 패널 토글 초기화

        // 🚀 [territory bootstrap] 페이지 로드 직후 타일 인덱스 + 현재 viewport 타일 미리 로드
        // _loadNewViewportTiles의 self-healing 가드만으로도 작동하지만,
        // 첫 moveend를 기다리지 않고 즉시 영토를 채우기 위함
        if (layerVisibility?.territoryPolygon) {
            try {
                await _ensureTileIndex();
                await _loadNewViewportTiles();
                if (typeof updateVisibleTerritories === 'function') {
                    updateVisibleTerritories();
                }
            } catch (e) {
                console.warn('[territory] initial bootstrap failed:', e);
            }
        }

        // 🌡️ [Warm Cache] idle 구간에서 저줌 광역 타일 사전 로드
        // → 줌아웃 시 빈 타일 없이 즉시 렌더링 가능
        // → desktop은 더 넓은 범위, mobile은 제한적으로 수행
        (function _scheduleWarmCache() {
            // 3D 전용 운영에서는 전체 169개 영토 타일을 idle 시점에
            // 미리 파싱하지 않는다. 현재 화면 범위는 moveend에서 로드한다.
            const ENABLE_FULL_TERRITORY_WARM_CACHE = false;
            if (!ENABLE_FULL_TERRITORY_WARM_CACHE) return;
            async function _warmLowZoomTiles() {
                if (!_tileIndexCache || allTerritoriesLoaded) return;
                // 타일 인덱스 전체를 bounds 기준으로 가져오되, 이미 로드된 것은 스킵
                const warmCandidates = _tileIndexCache.filter(t => !_loadedTileFiles.has(t.filename));
                if (warmCandidates.length === 0) return;
                const bgLimit = _tileDeviceMode === 'mobile' ? 2 : 4;
                const origin  = window.location.origin;
                const version = new Date().toDateString();
                const isDev   = (location.hostname === 'localhost' || location.hostname === '127.0.0.1');
                if (isDev) console.debug(`[WarmCache] ${warmCandidates.length}개 타일 사전 로드 시작 (device: ${_tileDeviceMode})`);
                for (let i = 0; i < warmCandidates.length; i += bgLimit) {
                    if (allTerritoriesLoaded) break; // 이미 완료됐으면 중단
                    const batch = warmCandidates.slice(i, i + bgLimit);
                    try {
                        const features = (await Promise.all(
                            batch.map(t => _fetchTile(t, origin, _tilesBasePathCache, version))
                        )).flat();
                        _mergeFeatures(features);
                    } catch(e) { /* warm cache 실패는 무시 */ }
                }
                if (_tileIndexCache && _loadedTileFiles.size >= _tileIndexCache.length) {
                    allTerritoriesLoaded = true;
                    _updateTerritoryBtn();
                    if (isDev) console.debug('[WarmCache] 전체 타일 warm cache 완료');
                }
            }

            // 앱 초기화 완료 후 idle 구간에서 실행
            if ('requestIdleCallback' in window) {
                requestIdleCallback(() => { void _warmLowZoomTiles(); }, { timeout: 3000 });
            } else {
                setTimeout(() => { void _warmLowZoomTiles(); }, 1500);
            }
        })();

        // 🚩 [추가] initialize 완료 후 현재 연도 이벤트 재확인 (events 백그라운드 로딩 타이밍 보정)
        if (typeof checkAndDisplayEvent === 'function' && typeof getCurrentYearMonth === 'function') {
            setTimeout(() => {
                const { year: _iy, month: _im } = getCurrentYearMonth();
                checkAndDisplayEvent(_iy, _im);
            }, 1500); // 백그라운드 events 로드 완료를 위해 1.5초 후 재확인
        }

