        createDynastyTimeline(); // 🚩 [수정] 연대표 생성 함수 호출 (내부에서 tick도 생성)
        
        // 🚩 [수정] 초기에는 timeline-sidebar 표시 (연대표가 사라지지 않도록)
        // 🚩 [수정] timeline-sidebar 초기 상태 설정 (layerVisibility에 따라)
        const timelineSidebar = document.getElementById('timeline-sidebar');
