        // 🚩 [추가] 역사 기록의 국가 입력 필드에 대한 자동 완성 이벤트 리스너 (이벤트 위임)
        // 드롭다운은 body 수준 fixed 엘리먼트로 표시 → overflow 클리핑 및 stacking context 문제 해결 (3D 모드 포함)
        let _historyAcDropdown = null; // 전역 floating 드롭다운
        let _historyAcActiveInput = null;

        function _getOrCreateHistoryAcDropdown() {
            if (!_historyAcDropdown) {
                _historyAcDropdown = document.createElement('div');
                _historyAcDropdown.id = 'history-ac-floating';
                _historyAcDropdown.style.cssText = 'position:fixed;display:none;background:#3e4a56;border:1px solid #5d7185;z-index:2147482600;max-height:180px;overflow-y:auto;border-radius:0 0 4px 4px;min-width:160px;box-shadow:0 8px 22px rgba(0,0,0,.6);';
                document.body.appendChild(_historyAcDropdown);
            }
            return _historyAcDropdown;
        }

        function _positionHistoryAcDropdown(inputEl) {
            const dd = _getOrCreateHistoryAcDropdown();
            const r = inputEl.getBoundingClientRect();
            dd.style.top  = Math.min(r.bottom + 2, window.innerHeight - Math.min(180, dd.scrollHeight || 180) - 8) + 'px';
            dd.style.left = r.left + 'px';
            dd.style.width = Math.max(r.width, 190) + 'px';
            dd.style.display = 'block';
        }

        function _hideHistoryAcDropdown() {
            if (_historyAcDropdown) _historyAcDropdown.style.display = 'none';
            _historyAcActiveInput = null;
        }

        document.getElementById('castleHistoryList').addEventListener('input', (e) => {
            if (e.target.matches('input.history-start-year,input.history-start-month,input.history-end-year,input.history-end-month')) {
                rebuildCastleHistoryGapButtons();
            }
            if (e.target.classList.contains('history-country-name')) {
                const input = e.target;
                const hiddenInput = input.nextElementSibling; // hidden country-id
                const query = input.value.toLowerCase();
                const dd = _getOrCreateHistoryAcDropdown();
                dd.innerHTML = '';

                // 입력 내용이 바뀌면 hidden id 초기화
                hiddenInput.value = '';
                input.style.borderColor = '';
                _historyAcActiveInput = input;

                if (query.length === 0) {
                    _hideHistoryAcDropdown();
                    return;
                }

                const filteredCountries = getCountrySearchMatches(query);

                filteredCountries.forEach(match => {
                    const country = match.country;
                    const item = document.createElement('div');
                    item.style.cssText = 'padding:8px 10px;cursor:pointer;font-size:13px;color:#ecf0f1;border-bottom:1px solid rgba(93,113,133,0.3);';
                    item.textContent = getCountrySearchResultLabel(match);
                    item.addEventListener('mouseover', () => item.style.background = '#5d7185');
                    item.addEventListener('mouseout',  () => item.style.background = '');
                    item.addEventListener('mousedown', (ev) => {
                        ev.preventDefault();
                        input.value = match.displayName;
                        hiddenInput.value = country._id;
                        input.style.borderColor = '#2ecc71';
                        _hideHistoryAcDropdown();

                        // 국가 선택 시 시작/종료 연도·월 자동 입력
                        const row = input.closest('.history-record-row');
                        const startYearInput  = row.querySelector('input.history-start-year');
                        const startMonthInput = row.querySelector('input.history-start-month');
                        const endYearInput    = row.querySelector('input.history-end-year');
                        const endMonthInput   = row.querySelector('input.history-end-month');
                        const isEmptyHistoryDateField = (field) =>
                            field && String(field.value ?? '').trim() === '';
                        const periodSource = match.phase || country;
                        const periodStartYear = periodSource.start_year ?? periodSource.start;
                        const periodStartMonth = periodSource.start_month;
                        const periodEndYear = periodSource.end_year ?? periodSource.end;
                        const periodEndMonth = periodSource.end_month;
                        if (isEmptyHistoryDateField(startYearInput) && periodStartYear != null && periodStartYear !== '') {
                            startYearInput.value = periodStartYear;
                        }
                        if (isEmptyHistoryDateField(startMonthInput) && periodStartMonth != null && periodStartMonth !== '') {
                            startMonthInput.value = periodStartMonth;
                        }
                        if (isEmptyHistoryDateField(endYearInput) && periodEndYear != null && periodEndYear !== '') {
                            endYearInput.value = periodEndYear;
                        }
                        if (isEmptyHistoryDateField(endMonthInput) && periodEndMonth != null && periodEndMonth !== '') {
                            endMonthInput.value = periodEndMonth;
                        }
                    });
                    dd.appendChild(item);
                });

                if (filteredCountries.length > 0) {
                    _positionHistoryAcDropdown(input);
                } else {
                    _hideHistoryAcDropdown();
                }
            }
        });

        // 🚩 [추가] blur 시 드롭다운 미선택 경고 (타이핑만 하고 선택 안 한 경우)
